import { subDays } from "date-fns";
import { buildGroup, buildGroupUser } from "@server/test/factories";
import Group from "./Group";
import GroupUser from "./GroupUser";

const backdate = (groupId: string) =>
  Group.update(
    { updatedAt: subDays(new Date(), 1) },
    { where: { id: groupId }, silent: true, hooks: false, validate: false }
  );

describe("GroupUser", () => {
  describe("hooks", () => {
    it("should bump group updatedAt when a member is added", async () => {
      const group = await buildGroup();
      await backdate(group.id);
      await group.reload();
      const before = group.updatedAt;

      await buildGroupUser({ groupId: group.id, teamId: group.teamId });

      await group.reload();
      expect(group.updatedAt.getTime()).toBeGreaterThan(before.getTime());
    });

    it("should bump group updatedAt when a member is removed", async () => {
      const group = await buildGroup();
      const groupUser = await buildGroupUser({
        groupId: group.id,
        teamId: group.teamId,
      });
      await backdate(group.id);
      await group.reload();
      const before = group.updatedAt;

      await groupUser.destroy();

      await group.reload();
      expect(group.updatedAt.getTime()).toBeGreaterThan(before.getTime());
    });

    it("should bump group updatedAt on bulk destroy with individual hooks", async () => {
      const group = await buildGroup();
      const groupUser = await buildGroupUser({
        groupId: group.id,
        teamId: group.teamId,
      });
      await backdate(group.id);
      await group.reload();
      const before = group.updatedAt;

      await GroupUser.destroy({
        where: { userId: groupUser.userId },
        individualHooks: true,
      });

      await group.reload();
      expect(group.updatedAt.getTime()).toBeGreaterThan(before.getTime());
    });
  });
});
